mkdir -p /tmp/probe && cat > /tmp/probe/run.mjs <<'EOF'
import { spawnSync } from 'node:child_process';
const BIN = '/workspace/dataset/test1_executable';
function esc(s){
  return JSON.stringify(s);
}
const cases = JSON.parse(process.argv[2]);
for (const argv of cases) {
  const r = spawnSync(BIN, argv, {encoding:'buffer'});
  console.log('ARGV=' + JSON.stringify(argv));
  console.log('  EXIT=' + r.status + (r.signal? ' SIGNAL='+r.signal : ''));
  console.log('  OUT=' + esc(r.stdout.toString('utf8')));
  console.log('  ERR=' + esc(r.stderr.toString('utf8')));
  console.log('');
}
EOF
